import{_ as t,o as a,c as o,ah as n}from"./chunks/framework.BsNNkeaH.js";const u=JSON.parse('{"title":"Internal edPage panel","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/admission/staff-edpage/index.md","filePath":"src/en/admission/staff-edpage/index.md"}'),s={name:"en/admission/staff-edpage/index.md"};function i(r,e,l,d,h,g){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="internal-edpage-panel" tabindex="-1">Internal edPage panel <a class="header-anchor" href="#internal-edpage-panel" aria-label="Permalink to &quot;Internal edPage panel&quot;">​</a></h1><p>The internal Era Admission panel is the tool reserved for the edPage team to manage the lifecycle of schools signed up online: granting a license, ending a demo early, or purging an expired school. It&#39;s also where the team edits Era Admission&#39;s <strong>landing page</strong> and handles the <strong>contact requests</strong> it receives. It has nothing to do with a client school&#39;s own user account — it&#39;s an entirely separate access.</p><p>The menu at the top of the panel leads to its three screens: <strong>Schools</strong>, <strong>Landing page</strong> and <strong>Contact requests</strong>. <strong>View landing page</strong> opens the public page in a new tab.</p><h2 id="logging-into-the-panel" tabindex="-1">Logging into the panel <a class="header-anchor" href="#logging-into-the-panel" aria-label="Permalink to &quot;Logging into the panel&quot;">​</a></h2><ol><li>Go to the staff login page, reachable on ERA&#39;s central domain (the one hosting the signup site, not a school&#39;s subdomain).</li><li>Enter your <strong>staff account</strong> email address and password — this account is independent of any school account, it only exists for the edPage team.</li><li>Submit. You land on the schools list.</li></ol><p>The staff login form is deliberately minimal (no public signup, no two-factor authentication, no self-service password reset): staff accounts are created by hand, not through a public flow.</p><h2 id="viewing-the-schools-list" tabindex="-1">Viewing the schools list <a class="header-anchor" href="#viewing-the-schools-list" aria-label="Permalink to &quot;Viewing the schools list&quot;">​</a></h2><p>Once logged in, the &quot;Schools&quot; page lists every school that has signed up, with for each one:</p><ul><li>its name and subdomain;</li><li>its <strong>status</strong>: free, demo, licensed, or expired;</li><li>its active <strong>modules</strong> (none on free; all on demo; whichever are actually licensed on licensed; none on expired);</li><li>its <strong>hosting formula</strong> (self-hosted or managed);</li><li>the demo end date, the date maintenance is paid through, and how long the school has been expired, whichever applies.</li></ul><p>Each row then offers the actions available for that school, described below — some only appear for certain statuses.</p><h2 id="granting-a-license" tabindex="-1">Granting a license <a class="header-anchor" href="#granting-a-license" aria-label="Permalink to &quot;Granting a license&quot;">​</a></h2><p>Available for any school, regardless of its current status.</p><ol><li>On the row for the school in question, click <strong>License</strong>.</li><li>In the dialog, check the modules to grant (or the &quot;Full offer&quot; option for every module at once). Each module&#39;s price is shown next to its name.</li><li>Fill in, if needed, the date maintenance is paid through. Left blank, it defaults to one year from today.</li><li>Confirm with <strong>Grant license</strong>.</li></ol><p>The school immediately moves to &quot;Licensed&quot; status, with the checked modules active, while staying hosted on edPage&#39;s infrastructure (the &quot;Managed&quot; formula). If the school ultimately needs to host its own installation instead (the &quot;Self-hosted&quot; formula), that switch is done through a dedicated command-line tool, outside this panel — don&#39;t use this action for that case.</p><p>This action can also be used to <strong>modify</strong> the license of an already licensed school (adding a module, extending maintenance): simply apply it again with the new values.</p><h2 id="ending-a-demo-manually" tabindex="-1">Ending a demo manually <a class="header-anchor" href="#ending-a-demo-manually" aria-label="Permalink to &quot;Ending a demo manually&quot;">​</a></h2><p>Available only for a school with &quot;Demo&quot; status. The action doesn&#39;t appear on other statuses.</p><ol><li>On the school&#39;s row, click <strong>End demo</strong>.</li><li>Confirm in the dialog — the action is immediate.</li></ol><p>The school moves to &quot;Expired&quot; status and switches to read-only, exactly as if its demo had ended naturally at its scheduled deadline. Use this action to end a demo before its normal term (for example at the school&#39;s request, or in case of misuse) — it isn&#39;t needed in the ordinary course of things, since the demo ends on its own.</p><h2 id="purging-an-expired-school" tabindex="-1">Purging an expired school <a class="header-anchor" href="#purging-an-expired-school" aria-label="Permalink to &quot;Purging an expired school&quot;">​</a></h2><p>Available only for a school with &quot;Expired&quot; status. This action is <strong>final and irreversible</strong>.</p><ol><li>On the school&#39;s row, click <strong>Purge</strong>.</li><li>Read the warning message in the dialog carefully: it states that the school, its database, and its storage will be deleted immediately, with no grace period and no way to undo it.</li><li>Confirm with <strong>Delete permanently</strong>.</li></ol><p>In the ordinary course of things, a school expired for too long is purged automatically once its grace period elapses. Use this manual action only to purge a school ahead of that automatic deadline — for example at the school&#39;s explicit request to delete its data without waiting.</p><h2 id="editing-the-landing-page" tabindex="-1">Editing the landing page <a class="header-anchor" href="#editing-the-landing-page" aria-label="Permalink to &quot;Editing the landing page&quot;">​</a></h2><p>The landing page is the public page shown at Era Admission&#39;s main address (the central domain, not a school&#39;s subdomain). It presents the offer to schools and leads to the free signup or to a proposal request. No price appears on it: prices stay in the personalised proposal sent to each school.</p><p>The <strong>Landing page</strong> screen lists the parts of the page, in display order:</p><table tabindex="0"><thead><tr><th>Part</th><th>Editable content</th><th>Shown</th></tr></thead><tbody><tr><td><strong>Header</strong></td><td>Headline title and text</td><td>Always</td></tr><tr><td><strong>Free offer</strong></td><td>Title and text about ERA Admissions</td><td>If <strong>Show</strong> is ticked</td></tr><tr><td><strong>Modules</strong></td><td>Title, text and one card per module</td><td>If <strong>Show</strong> is ticked and there is a card</td></tr><tr><td><strong>Formulas</strong></td><td>Title, text and one card per formula</td><td>If <strong>Show</strong> is ticked and there is a card</td></tr><tr><td><strong>Onboarding</strong></td><td>Title, text and one card per step</td><td>If <strong>Show</strong> is ticked and there is a card</td></tr><tr><td><strong>Frequently asked questions</strong></td><td>Title, questions and answers</td><td>If <strong>Show</strong> is ticked and there is a question</td></tr><tr><td><strong>Contact</strong></td><td>Title and text above the form</td><td>Always</td></tr></tbody></table><p>The header buttons (<strong>Create my free space</strong> and <strong>Request a proposal</strong>) and the contact form&#39;s fields aren&#39;t editable.</p><h3 id="default-texts" tabindex="-1">Default texts <a class="header-anchor" href="#default-texts" aria-label="Permalink to &quot;Default texts&quot;">​</a></h3><p>Each text is entered in French and in English. A field left empty shows its language&#39;s default text, visible greyed out in the field. You only need to fill in what you want to change. If you write in a single language, that text is reused for the other.</p><p>At first deployment, the modules, formulas, steps and FAQ are already filled in from the commercial proposal. Edit or delete them freely.</p><h3 id="managing-cards-and-questions" tabindex="-1">Managing cards and questions <a class="header-anchor" href="#managing-cards-and-questions" aria-label="Permalink to &quot;Managing cards and questions&quot;">​</a></h3><ul><li><strong>Add a card</strong> or <strong>Add a question</strong> opens a form; the title (or the question and answer) is required in at least one language.</li><li>The <strong>Move up</strong> and <strong>Move down</strong> arrows change the display order. For <strong>Onboarding</strong>, that order is also the step numbering on the page.</li><li><strong>Edit</strong> reopens the item; <strong>Delete</strong> removes it permanently.</li></ul><p>Each block shows its state: <strong>Shown</strong>, <strong>Hidden</strong> (unticked) or <strong>Empty, not shown</strong> (no card or question). Saving is immediate.</p><h2 id="handling-contact-requests" tabindex="-1">Handling contact requests <a class="header-anchor" href="#handling-contact-requests" aria-label="Permalink to &quot;Handling contact requests&quot;">​</a></h2><p>The landing page&#39;s form sends its requests to the <strong>Contact requests</strong> screen. The number of requests still to handle shows as a badge next to its name, in the panel&#39;s menu.</p><p>Each request shows the school, the person&#39;s name, the date, the language they were browsing the landing page in, their email and phone (clickable) and their message. Requests <strong>To handle</strong> come first, newest first.</p><p>Once you have got back to the school, click <strong>Mark as handled</strong>. <strong>Mark as to handle</strong> undoes it.</p>',38)])])}const p=t(s,[["render",i]]);export{u as __pageData,p as default};
